// ===========================================================================
// phase hook — ONE entry point for Claude Code and Codex lifecycle hooks
// ===========================================================================
//
// Both tools send the event as JSON on stdin with `hook_event_name`, `cwd`, and
// for tool events `tool_name` + `tool_input`. Codex edits files through
// `apply_patch` (patch text); Claude Code through Write/Edit/MultiEdit.
// Contract: exit 2 + stderr blocks a PreToolUse; stdout JSON carries context.

export const STEP_NAMES = {
  discover: 'Step 1 of 4 — describe the app',
  mock: 'Step 2 of 4 — preview the design',
  build: 'Step 3 of 4 — build it for real',
  ship: 'Step 4 of 4 — go live',
};

export const PLAIN_LANGUAGE =
  'Talk to the user as a friendly product manager would talk to a business owner: plain words, short answers, one question at a time. ' +
  'Never show them internal words such as phase, gate, hook, SPEC, R-001/S-001 ids, npx, CLI commands, JSON, or file paths unless they ask. ' +
  'Describe progress as the four steps: describe the app, preview the design, build it for real, go live. ' +
  'When something is blocked, fix it yourself and tell them in one plain sentence what you changed and why.';

export function readRuleFile(rulesDir, topic) {
  if (!rulesDir) return '';
  try {
    return readFileSync(join(rulesDir, `${topic}.md`), 'utf-8').trim();
  } catch {
    return '';
  }
}

export function hookContext(event, text) {
  return JSON.stringify({ hookSpecificOutput: { hookEventName: event, additionalContext: text } });
}

export function isApprovalPrompt(prompt) {
  const p = String(prompt || '').trim().toLowerCase().replace(/[.!]+$/, '');
  return p === 'approve' || p === 'approved' || p === 'i approve' || p === '/piezas:approve' || p === '/approve';
}

export function patchTextFrom(input) {
  if (typeof input === 'string') return input.includes('*** Begin Patch') ? input : null;
  if (Array.isArray(input)) {
    for (const part of input) {
      const found = patchTextFrom(part);
      if (found) return found;
    }
    return null;
  }
  if (input && typeof input === 'object') {
    for (const value of Object.values(input)) {
      const found = patchTextFrom(value);
      if (found) return found;
    }
  }
  return null;
}

// parsePatch — Codex's apply_patch envelope -> [{ path, added }].
export function parsePatch(text) {
  const files = [];
  let current = null;
  for (const line of String(text).split('\n')) {
    const header = /^\*\*\* (Add|Update|Delete) File: (.+)$/.exec(line);
    const move = /^\*\*\* Move to: (.+)$/.exec(line);
    if (header) {
      current = { path: header[2].trim(), op: header[1].toLowerCase(), added: [] };
      files.push(current);
    } else if (move && current) {
      current = { path: move[1].trim(), op: 'move', added: current.added };
      files.push(current);
    } else if (current && line.startsWith('+')) {
      current.added.push(line.slice(1));
    }
  }
  return files.map((f) => ({ path: f.path, op: f.op, added: f.added.join('\n') }));
}

export function shellCommandFrom(input) {
  const cmd = input?.command ?? input?.cmd;
  if (Array.isArray(cmd)) return cmd.join(' ');
  return typeof cmd === 'string' ? cmd : '';
}

export function preToolUse(payload, cwd) {
  const tool = typeof payload.tool_name === 'string' ? payload.tool_name : '';
  const input = payload.tool_input ?? {};

  const patch = tool === 'apply_patch' || tool === 'Edit' || tool === 'Write' ? patchTextFrom(input) : null;
  if (patch) {
    for (const file of parsePatch(patch)) {
      const verdict = phaseGuard({ cwd, tool: 'Write', file: file.path, content: file.added });
      if (verdict.exitCode === 2) return verdict;
    }
    return guardAllow();
  }

  if (tool === 'Bash' || tool === 'shell' || tool === 'exec_command') {
    return phaseGuard({ cwd, tool: 'Bash', command: shellCommandFrom(input) });
  }

  if (tool === 'Write' || tool === 'Edit' || tool === 'MultiEdit') {
    const content =
      typeof input.content === 'string'
        ? input.content
        : typeof input.new_string === 'string'
          ? input.new_string
          : Array.isArray(input.edits)
            ? input.edits.map((e) => (e && typeof e.new_string === 'string' ? e.new_string : '')).join('\n')
            : undefined;
    return phaseGuard({ cwd, tool, file: input.file_path, content });
  }
  return guardAllow();
}

export const OFFLINE_FETCH = () => Promise.reject(new Error('offline'));
// Doctor codes for the Hard No rules: secret exposure (PZ001/PZ002), provider
// token storage (PZ004-PZ006), local database (PZ020), public-prefixed secret (PZ021).
export const HARD_NO_CODES = new Set(['PZ001', 'PZ002', 'PZ004', 'PZ005', 'PZ006', 'PZ020', 'PZ021']);

export async function phaseHook(payload, options = {}) {
  const done = (exitCode = 0, stdout = '', stderr = '') => ({ exitCode, stdout, stderr });
  if (!payload || typeof payload !== 'object') return done();
  const event = payload.hook_event_name;
  const cwd = typeof payload.cwd === 'string' && payload.cwd ? payload.cwd : process.cwd();
  const session = sessionRoot(cwd);
  const root = session.root;
  if (root && event) writeGuardMarker(root, payload);

  try {
    if (event === 'PreToolUse') {
      const verdict = preToolUse(payload, cwd);
      if (verdict.exitCode !== 2) return done();
      // Structured deny: both Claude Code and Codex read it, show it as a clean
      // "blocked" notice, and hand the reason to the model as a work order.
      return done(
        0,
        JSON.stringify({
          hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: verdict.reason },
        }),
      );
    }

    if (event === 'SessionStart') {
      const signInLine = signInContext(options.env ?? process.env, options.cliPath);
      const cliLine = options.cliPath
        ? `Piezas command (run it with the shell tool): node "${options.cliPath}" <args> — e.g. node "${options.cliPath}" phase status --context. ` +
          `Wherever a Piezas message says \`npx piezas ...\`, run node "${options.cliPath}" ... instead.`
        : '';
      if (!root) {
        const several = (session.several ?? []).map((d) => `${toPosix(relative(resolve(cwd), d))}/`);
        return done(
          0,
          hookContext(
            'SessionStart',
            ['The Piezas plugin is installed. If the user wants to build a business app (bookings, CRM, intake, projects, a client portal), use the piezas skill to guide them.',
              several.length ? `Piezas projects below this folder: ${several.join(', ')}. Ask which one they mean, then work inside it.` : '',
              signInLine, cliLine]
              .filter(Boolean)
              .join('\n'),
          ),
        );
      }
      const state = loadState(root);
      const gaps = gateGaps(root, state);
      const sandbox = isSandboxProject(root);
      const manifest = sandbox ? readManifestSafe(root) : null;
      const appUrl = manifest?.deploy?.url || (manifest?.appName ? `https://${slugifyAppName(manifest.appName)}.${new URL(DEFAULT_APPS_URL).host}` : '');
      const parts = [
        `[Piezas] This project is a Piezas app. ${STEP_NAMES[state.phase]}.`,
        session.below
          ? `The project is in the folder ${toPosix(relative(resolve(cwd), root))}/ below this session's folder: work there, and run every Piezas command from inside it.`
          : '',
        PLAIN_LANGUAGE,
        sandbox
          ? `${SANDBOX_NOTE} Use the normal Piezas commands (init, deploy, env, status); they run against the simulator. ` +
            `The app's address will be ${appUrl} (simulated). The running app's own data calls cannot reach real Piezas until it is connected, so test screens with sample data.`
          : signInLine,
        cliLine,
        readRuleFile(options.rulesDir, 'core'),
        options.rulesDir
          ? `Before writing code against a Piezas service, read its rules file in ${options.rulesDir}: entities.md, users.md, integrations.md, calendar.md, documents.md, deploy.md, testing.md, patterns.md.`
          : '',
        importNote(root, state.phase),
        'Project state (for you, not for the user):',
        ...contextLines(state, gaps),
      ];
      return done(0, hookContext('SessionStart', parts.filter(Boolean).join('\n\n')));
    }

    if (event === 'UserPromptSubmit') {
      // A secret typed into the chat is stopped before the AI sees it: chat
      // history can be kept for a long time. Runs in every folder.
      const secret = secretInPrompt(payload.prompt);
      if (secret) {
        return done(0, JSON.stringify({ decision: 'block', reason: secretBlockReason(secret) }));
      }
      if (!root) return done();
      let state = loadState(root);
      const notes = [];
      const said = String(payload.prompt || '').trim().toLowerCase().replace(/[.!]+$/, '');
      if (said === DEPLOY_ANYWAY || said === '/piezas:deploy-anyway') {
        const pending = pendingDeployRisk(root);
        if (pending?.fingerprint) {
          recordDeployRisk(root, pending.fingerprint, 'user-prompt');
          state = loadState(root);
          notes.push('The owner confirmed (they typed "deploy anyway") putting this version live despite the problems found. Run the deploy again now; tell them in one sentence that it is going live and that fixing the problem is still recommended.');
        } else {
          notes.push('The owner typed "deploy anyway", but no deploy is waiting for confirmation. Tell them where things stand in one sentence.');
        }
      }
      const importReply = recordOwnerReply(root, payload.prompt);
      if (importReply) notes.push(importReply);
      if (isApprovalPrompt(payload.prompt)) {
        if (state.phase === 'mock') {
          if (!approvalFor(state, 'mock')) {
            const approval = { gate: 'mock', by: 'user', via: 'user-prompt', at: new Date().toISOString() };
            state = saveState(root, { ...state, approvals: [...state.approvals, approval] });
          }
          notes.push('The customer approved the design (they typed "approve" themselves), and it is recorded. Move to the next step now and tell them in one sentence what happens next.');
        } else {
          notes.push('The customer typed "approve", but there is nothing waiting for approval right now. Tell them where things stand in one sentence.');
        }
      }
      const reminder =
        `[Piezas] ${STEP_NAMES[state.phase]} (phase: ${state.phase}). ` +
        'Always: no local database; PIEZAS_API_KEY server-side only; no provider tokens in the app; plain language with the user.';
      return done(0, hookContext('UserPromptSubmit', [reminder, ...notes].join(' ')));
    }

    if (event === 'Stop') {
      if (!root || payload.stop_hook_active) return done();
      const state = loadState(root);
      if (state.phase === 'discover') return done();
      // Only the Hard No findings hold a turn open. Ordinary build gaps (tests
      // still to write, config to finish) belong to the work, not to every
      // reply — otherwise a user's quick question turns into a forced fix-up.
      const errors = newHardNoFindings(root);
      if (errors.length === 0) return done();
      const lines = errors.slice(0, 8).map((f) => `- ${f.code} ${f.file ?? ''}: ${f.message}`);
      return done(
        0,
        JSON.stringify({
          decision: 'block',
          reason:
            `Piezas check found ${errors.length} problem(s) that would break the app or its rules. Fix them before finishing:\n${lines.join('\n')}`,
        }),
      );
    }
  } catch (error) {
    // Fail open on our own bugs: a hook that crashes every call is worse than one that misses.
    return done(0, '', `piezas hook: ${error?.message || error}`);
  }
  return done();
}

// ===========================================================================
// Secrets never go through the chat
// ===========================================================================

export const SECRET_PATTERNS = [
  { what: 'a Piezas secret key', re: /\bsk_(?:live|test)_[A-Za-z0-9]{12,}/ },
  { what: 'a Piezas agent token', re: /\bagt_(?:live|test)_[A-Za-z0-9]{12,}/ },
  { what: 'an Anthropic API key', re: /\bsk-ant-[A-Za-z0-9_-]{20,}/ },
  { what: 'an OpenAI API key', re: /\bsk-(?:proj-|svcacct-)?[A-Za-z0-9_-]{32,}/ },
  { what: 'a Stripe secret key', re: /\b(?:rk|sk)_(?:live|test)_[A-Za-z0-9]{16,}/ },
  { what: 'an AWS access key', re: /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/ },
  { what: 'a GitHub token', re: /\b(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{40,})/ },
  { what: 'a Slack token', re: /\bxox[abprs]-[A-Za-z0-9-]{10,}/ },
  { what: 'a Google API key', re: /\bAIza[0-9A-Za-z_-]{35}\b/ },
  { what: 'a private key', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----/ },
];
// NAME=value (or NAME: value) where the name says it is secret and the value
// looks like one: long, no spaces, letters and digits, not a placeholder.
export const SECRET_ASSIGNMENT = /\b((?:[A-Za-z][A-Za-z0-9_]*)?(?:KEY|SECRET|TOKEN|PASSWORD|PASSWD|PWD))\s*[:=]\s*["']?([^\s"']{12,})/gi;

export function looksLikeSecretValue(name, value) {
  if (/PUBLISHABLE|PUBLIC_KEY$/i.test(name)) return false;
  if (/^pk_/.test(value)) return false;
  if (/^(?:your|my|example|placeholder|changeme|xxx|<|\$\{?|process\.env)/i.test(value) || /\.\.\.|x{4,}|\*{4,}/i.test(value)) return false;
  return /[A-Za-z]/.test(value) && /[0-9]/.test(value);
}

export function secretInPrompt(prompt) {
  const text = String(prompt || '');
  if (!text) return null;
  for (const { what, re } of SECRET_PATTERNS) {
    if (re.test(text)) return what;
  }
  for (const m of text.matchAll(SECRET_ASSIGNMENT)) {
    if (looksLikeSecretValue(m[1], m[2])) return `a value for ${m[1]}`;
  }
  return null;
}

export function secretBlockReason(what) {
  return `Piezas stopped this message before your AI tool saw it: it looks like it contains ${what}. ` +
    'Chats can be kept for a long time, so keys and passwords never go in them. Set it yourself instead: ' +
    'on the app page in the Piezas console (Hosting -> Environment), or in your own terminal with ' +
    '`npx piezas env set NAME=value`. Then send your message again without the value. ' +
    'If it was a real key, consider replacing it, since it was typed here.';
}

export function guardContent(options) {
  if (typeof options.content === 'string') return options.content;
  if (typeof options.contentFile === 'string' && options.contentFile && existsSync(options.contentFile)) {
    try {
      return readFileSync(options.contentFile, 'utf-8');
    } catch {
      return undefined;
    }
  }
  return undefined;
}

